import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom elementwise Sigmoid kernel
sigmoid_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>

__global__ void sigmoid_kernel(const float* input, float* output, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        output[idx] = 1.0f / (1.0f + expf(-input[idx]));
    }
}

torch::Tensor sigmoid_cuda(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int size = x.numel();
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    sigmoid_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}
"""

sigmoid_cpp_source = "torch::Tensor sigmoid_cuda(torch::Tensor x);"

sigmoid_module = load_inline(
    name='sigmoid_module',
    cpp_sources=sigmoid_cpp_source,
    cuda_sources=sigmoid_kernel_source,
    functions=['sigmoid_cuda'],
    verbose=True
)

# Fused Sum + LogSumExp kernel
fused_reduce_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cub/block/block_reduce.cuh>

template<int BLOCK_SIZE>
__global__ void fused_reduce_kernel(const float* input, float* output, int batch_size, int hidden_size) {
    typedef cub::BlockReduce<float, BLOCK_SIZE> BlockReduce;
    __shared__ typename BlockReduce::TempStorage temp_storage;

    float thread_sum = 0.0f;

    // First reduce along hidden dimension
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        thread_sum += input[blockIdx.x * hidden_size + i];
    }

    float block_sum = BlockReduce(temp_storage).Sum(thread_sum);

    __syncthreads();

    // Then compute exp and reduce across batch
    if (threadIdx.x == 0) {
        float exp_sum = expf(block_sum);
        atomicAdd(output, exp_sum);
    }
}

__global__ void final_log_kernel(float* output) {
    *output = logf(*output);
}

torch::Tensor fused_reduce_cuda(torch::Tensor x) {
    int batch_size = x.size(0);
    int hidden_size = x.size(1);
    auto options = torch::TensorOptions().dtype(x.dtype()).device(x.device());
    auto exp_sum = torch::zeros(1, options);
    auto output = torch::zeros(1, options);

    const int block_size = 256;
    fused_reduce_kernel<block_size><<<batch_size, block_size>>>(
        x.data_ptr<float>(), exp_sum.data_ptr<float>(), batch_size, hidden_size
    );

    final_log_kernel<<<1, 1>>>(exp_sum.data_ptr<float>());
    cudaMemcpy(output.data_ptr<float>(), exp_sum.data_ptr<float>(), sizeof(float), cudaMemcpyDeviceToDevice);
    return output;
}
"""

fused_reduce_cpp_source = "torch::Tensor fused_reduce_cuda(torch::Tensor x);"

fused_reduce_module = load_inline(
    name='fused_reduce_module',
    cpp_sources=fused_reduce_cpp_source,
    cuda_sources=fused_reduce_kernel_source,
    functions=['fused_reduce_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, output_size):
        super(ModelNew, self).__init__()
        self.linear1 = nn.Linear(input_size, hidden_size)
        self.linear2 = nn.Linear(hidden_size, output_size)
        self.sigmoid = sigmoid_module
        self.fused_reduce = fused_reduce_module

    def forward(self, x):
        x = self.linear1(x)
        x = self.sigmoid.sigmoid_cuda(x)
        x = self.fused_reduce.fused_reduce_cuda(x)
        return x
